mapper.insert:
CREATE VIEW view_${tableName} AS
SELECT gid, geom, bsm, minx, miny, maxx, maxy ${fields}
FROM ${tableName}

mapper.select:
SELECT
row_to_json(fc)
FROM (
SELECT
'FeatureCollection' AS type,
'212' AS id,
array_to_json(array_agg(f)) AS features
FROM (
SELECT
'Feature' AS type

    ,ST_AsGeoJSON(geom)::json as geometry

,(
SELECT
row_to_json(t)
FROM (
SELECT

    ${baseFields}


    ${allFields}

) AS t
) AS properties
FROM ${tableName}


        and bsm like concat('%',#{req.bsm},'%')


        and bsm in

            #{item}




    limit ${size} offset ${offset}

) AS f
) AS fc

select
count(1)
from ${tableName}


        and bsm in

            #{item}

SELECT
row_to_json(fc)
FROM (
SELECT
'FeatureCollection' AS type,
'212' AS id,
array_to_json(array_agg(f)) AS features
FROM (
SELECT
'Feature' AS type

    ,ST_AsGeoJSON(geom)::json as geometry

,(
SELECT
row_to_json(t)
FROM (
SELECT ${baseFields}
) AS t
) AS properties
FROM ${tableName}


        and ${tbbh} like concat('%',#{req.tbbh},'%')


limit ${size} offset ${offset}
) AS f
) AS fc

mapper.update:
UPDATE ${tableName}
SET geom = ST_SetSRID(geom, 4326)
WHERE calarea is null;

mapper.insert:
CREATE SEQUENCE ${tableName}_gid_seq INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;
create table IF NOT EXISTS ${tableName}
(
    like ${exploreLayerName} INCLUDING indexes including constraints including comments including defaults
);
alter table ${tableName}
alter column "gid" set default nextval('${tableName}_gid_seq');

insert into ${tableName}(gid, geom, bsm, layertype, properties, ${fields})
select gid, st_erase(geom, #{collectingLayerName}) geom, bsm, 'tewc', properties, ${fields}
FROM ${exploreLayerName};

mapper.update:
UPDATE ${tableName}
set expire = (case when yxqz > now() then 0 else 1 end)
where gid is not null;

mapper.select:
select
    gid,minx,miny,maxx,maxy,layertype,bsm,properties,${fields}
from ${tableName}

    where
        bsm like concat('%',#{bsm},'%')

limit ${size} offset ${offset}

select sum(t.count) as count, sum(t.mj) as area, t.code, t.value from (
select #{vo.code} as code, ${vo.code} as value, count(1) as count, sum(${vo.mj}) as mj from ${tableName} group by ${vo.code}
) t group by t.value,t.code order by area desc
